INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Vorkalkulation immer eine exakte Prognose?', 2, '[{"text": "Nein", "correct": true, "because": "Sie basiert auf Schätzungen"}, {"text": "Ja", "correct": false, "because": "Nicht immer präzise"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Vorkalkulation entscheidend?', 3, '[{"text": "Kostenschätzung", "correct": true, "because": "Bestimmt die Ausgabenbasis"}, {"text": "Farbe der Dokumente", "correct": false, "because": "Kein Einfluss"}, {"text": "Firmenlogo", "correct": false, "because": "Nur Darstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Vorkalkulation dient der Planung von Projekten. b) Sie berücksichtigt nur fixe Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Planung zentral, variable Kosten auch"}, {"text": "Beides stimmt", "correct": false, "because": "Fixe und variable Kosten"}, {"text": "Nur b) stimmt", "correct": false, "because": "Planung ist Kern"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element solltest du bei der Vorkalkulation eines IT-Projekts priorisieren?', 4, '[{"text": "Personalkosten", "correct": true, "because": "Dominanter Kostenfaktor in IT"}, {"text": "Farbe der Kalkulationssoftware", "correct": false, "because": "Irrelevant"}, {"text": "Marketingbudget", "correct": false, "because": "Sekundär zur Vorkalkulation"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Vorkalkulation ohne historische Daten erstellt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Schätzungen sind möglich"}, {"text": "Nein", "correct": false, "because": "Daten nicht zwingend nötig"}]');
